// Get the payment data from 'Get a single payment' node
const payment = $('Get a single payment').item.json.payment;
const PAYMENT_SYNC_FIELD_ID = '6326029000010763609';
const PAYMENT_SYNC_FIELD_LABEL = 'Synced to NetSuite';

if (!payment) {
  throw new Error('Payment data not found from "Get a single payment" node');
}

const syncField = (payment.custom_fields || []).find(field =>
  field.customfield_id === PAYMENT_SYNC_FIELD_ID ||
  field.field_id === PAYMENT_SYNC_FIELD_ID ||
  field.api_name === 'cf_synced_to_netsuite' ||
  field.placeholder === 'cf_synced_to_netsuite'
) || {};

// Prepare the update payload with all required fields
const payload = {
  customer_id: payment.customer_id,
  payment_mode: payment.payment_mode,
  amount: payment.amount,
  date: payment.date,
  reference_number: payment.reference_number,
  description: payment.description || '',
  invoices: (payment.invoices || []).map(inv => ({
    invoice_id: inv.invoice_id,
    amount_applied: inv.amount_applied
  })),
  custom_fields: [
    {
      customfield_id: PAYMENT_SYNC_FIELD_ID,
      label: syncField.label || PAYMENT_SYNC_FIELD_LABEL,
      value: true  // Mark as processed/synced to NetSuite
    }
  ]
};

// Optional: Add other fields if they exist in the original payment
if (payment.exchange_rate) {
  payload.exchange_rate = payment.exchange_rate;
}

if (payment.bank_charges) {
  payload.bank_charges = payment.bank_charges;
}

if (payment.tax_account_id) {
  payload.tax_account_id = payment.tax_account_id;
}

if (payment.account_id) {
  payload.account_id = payment.account_id;
}

const originalValue = payment.custom_field_hash?.cf_synced_to_netsuite_unformatted ?? syncField.value ?? null;

return {
  json: {
    payment_id: payment.payment_id,
    payload: payload,
    debug_info: {
      payment_sync_customfield_id: PAYMENT_SYNC_FIELD_ID,
      original_custom_field_value: originalValue,
      new_custom_field_value: true,
      payment_number: payment.payment_number,
      customer_name: payment.customer_name,
      amount: payment.amount
    }
  }
};

// Flatten Zoho payments and keep only those inside the configured date window.
const range = $('Set Date Range').first().json;
const fromDate = range.from_date || '';
const toDate = range.to_date || '';

const items = [];
for (const item of $input.all()) {
  const payments = item.json.payments || [];
  for (const payment of payments) {
    const d = payment.date || '';
    if (fromDate && d < fromDate) continue;   // before window
    if (toDate && d > toDate) continue;        // after window
    items.push({ json: payment });
  }
}

return items;

// Classify the Zoho PUT result as SUCCESS or ERROR (native, in-workflow log row).
const res = $input.first().json || {};
let payment = {};
try { payment = $('Get a single payment').item.json.payment || {}; } catch (e) {}

// Zoho returns code:0 on success; HTTP node puts an `error` object on failure.
const isError = !!res.error || (res.code !== undefined && res.code !== 0);
const message = isError
  ? (res.error?.message || res.message || 'Zoho update failed')
  : (res.message || 'Custom field updated (cf_synced_to_netsuite = true)');

return [{
  json: {
    status: isError ? 'ERROR' : 'SUCCESS',
    payment_id: payment.payment_id || '',
    payment_number: payment.payment_number || '',
    customer_name: payment.customer_name || '',
    amount: payment.amount || 0,
    date: payment.date || '',
    message,
  },
}];

// Log payments skipped because they are already synced.
let payment = {};
try { payment = $('Get a single payment').item.json.payment || {}; } catch (e) {}

return [{
  json: {
    status: 'SKIPPED',
    payment_id: payment.payment_id || '',
    payment_number: payment.payment_number || '',
    customer_name: payment.customer_name || '',
    amount: payment.amount || 0,
    date: payment.date || '',
    message: 'Already synced (cf_synced_to_netsuite = true). Skipped.',
  },
}];

// Aggregate all per-payment log rows collected through the loop.
// (Loop DONE branch receives every item routed back to the loop input.)
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.payment_id || r.payment_number));

const total = rows.length;
const updated = rows.filter(r => r.status === 'SUCCESS').length;
const skipped = rows.filter(r => r.status === 'SKIPPED').length;
const failed = rows.filter(r => r.status === 'ERROR').length;

return [{
  json: {
    summary: { total, updated, skipped, failed },
    failedRows: rows.filter(r => r.status === 'ERROR'),
    rows,
  },
}];
